    func removeContact(_ id: String, _ position: Int, _ size: Int) async throws -> Patient?
}

/// Keeps patients rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoPatientRepository: PatientRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findById(_ id: String) async throws -> Patient? {
        guard Bson.isObjectId(id) else { return nil }
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await database.find("patients", documentFilter, limit: 1).first.map(Patient.from)
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Patient, String> {
        var documentFilter: BsonDocument = [:]
        if let after { documentFilter["_id"] = ["$gt": try Bson.ofObjectId(after)] as BsonDocument }
        let rows = try await database.find("patients", documentFilter, sort: ["_id": 1], limit: limit + 1).map(Patient.from)
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last?.id : nil)
    }

    public func findByDocument(_ document: String) async throws -> Patient? {
        let documentFilter: BsonDocument = ["document": try Bson.ofText(document)]
        return try await database.find("patients", documentFilter, limit: 1).first.map(Patient.from)
    }

    public func findAllByBirth(_ birth: Date) async throws -> [Patient] {
        let documentFilter: BsonDocument = ["birth": try Bson.ofDate(birth)]
        return try await database.find("patients", documentFilter, sort: ["_id": 1]).map(Patient.from)
    }

    @discardableResult
    public func insert(_ entity: Patient) async throws -> Patient {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        let document = try entity.toDocument()
        try await write { try await database.insert("patients", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: Patient) async throws -> Patient {
        var entity = entity
        let now = try entity.toDocument()
        let fields = ["name", "birth", "weight", "balance", "document", "photo", "visits", "blood", "contacts", "insurance", "version"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            try await write { try await database.update("patients", ["_id": id], changes) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: Patient) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(entity.id!)]
        try await write { try await database.delete("patients", documentFilter) }
    }

    public func addContact(_ id: String, _ contact: Patient.Contact) async throws -> Patient? {
        guard Bson.isObjectId(id) else { return nil }
        let change: BsonDocument = ["$push": ["contacts": try Bson.ofNested(contact)] as BsonDocument, "$inc": ["version": Int32(1)] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("patients", documentFilter, change) }.map(Patient.from)
    }

    public func removeContact(_ id: String, _ position: Int, _ size: Int) async throws -> Patient? {
        guard Bson.isObjectId(id) else { return nil }
        let head: BsonDocument = ["$slice": ["$contacts", position] as BsonDocument]
        let tail: BsonDocument = ["$slice": ["$contacts", position + 1, max(size, 1)] as BsonDocument]
        let set: BsonDocument = ["contacts": ["$concatArrays": [head, tail] as BsonDocument] as BsonDocument, "version": ["$add": ["$version", Int32(1)] as BsonDocument] as BsonDocument]
        let change: BsonDocument = [["$set": set] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id), "contacts": ["$size": size] as BsonDocument]
        return try await write { try await database.change("patients", documentFilter, change) }.map(Patient.from)
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Patient", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

/// Keeps patients rows in memory, for tests and for trying the services without a database.
public final class MemoryPatientRepository: PatientRepository {
    private let rows = MemoryRows<Patient>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [Patient] {
        await rows.all.sorted(by: isBefore)
    }

    public func findById(_ id: String) async throws -> Patient? {
        await visible().first { $0.id == id }
    }

    public func list(after: String?, limit: Int) async throws -> CursorPage<Patient, String> {
        let rows = await visible().filter { row in after.map { isAfter(row, $0) } ?? true }
        let items = Array(rows.prefix(limit))
        return CursorPage(items: items, next: rows.count > limit ? items.last.map { $0.id! } : nil)
    }

    public func findByDocument(_ document: String) async throws -> Patient? {
        await visible().first { $0.document == document }
    }

    public func findAllByBirth(_ birth: Date) async throws -> [Patient] {
        await visible().filter { $0.birth == birth }
    }

    @discardableResult
    public func insert(_ entity: Patient) async throws -> Patient {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: Patient) async throws -> Patient {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    public func delete(_ entity: Patient) async throws {
        await rows.remove { sameKey($0, entity) }
    }

    public func addContact(_ id: String, _ contact: Patient.Contact) async throws -> Patient? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        found.contacts = (found.contacts ?? []) + [contact]
        found.version = (found.version ?? 0) + 1
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    public func removeContact(_ id: String, _ position: Int, _ size: Int) async throws -> Patient? {
        guard var found = await visible().first(where: { $0.id == id }) else { return nil }
        guard found.contacts?.count == size, position >= 0, position < size else { return nil }
        found.contacts?.remove(at: position)
        found.version = (found.version ?? 0) + 1
        let row = found
        await rows.store(row) { sameKey($0, row) }
        return row
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Patient, _ b: Patient) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Patient, _ b: Patient) -> Bool {
    return less(a.id, b.id)
}

/// Whether a row comes after a key.
fileprivate func isAfter(_ row: Patient, _ key: String) -> Bool {
    return less(key, row.id)
}

