import Foundation

/// Operations on patients. Each write runs in its own transaction.
public struct PatientService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Patient after checking it.
    @discardableResult
    public func createPatient(_ data: PatientCreate) async throws -> PatientRead {
        let values = Values(name: data.name.map(Optional.some), birth: data.birth.map(Optional.some), weight: data.weight.map(Optional.some), balance: data.balance.map(Optional.some), document: data.document.map(Optional.some), photo: data.photo.map(Optional.some), visits: data.visits.map(Optional.some), blood: data.blood.map(Optional.some), contacts: data.contacts.map(Optional.some), insurance: data.insurance.map(Optional.some), version: data.version.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Patient()
            applyValues(&entity, values)
            return try await read(uow.patients.insert(entity))
        }
    }

    /// The Patient with this key; notFound when there is none.
    public func getPatient(_ id: String) async throws -> PatientRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of patients after the key after (nil for the first page), by primary key.
    public func listPatients(after: String?, limit: Int) async throws -> CursorPage<PatientRead, String> {
        try await unitOfWork.patients.list(after: after, limit: limit).map(read)
    }

    /// Changes the given values of a Patient, read at version.
    @discardableResult
    public func updatePatient(_ id: String, _ changes: PatientUpdate, version: Int) async throws -> PatientRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Patient", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            current.version = version + 1
            return try await read(uow.patients.update(current))
        }
    }

    /// Deletes a Patient.
    public func deletePatient(_ id: String, version: Int) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Patient", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            try await uow.patients.delete(current)
        }
    }

    /// The Patient with this document, or nil.
    public func findPatientByDocument(_ document: String) async throws -> PatientRead? {
        try await unitOfWork.patients.findByDocument(document).map(read)
    }

    /// Adds an item to contacts, read at version.
    @discardableResult
    public func addContact(_ id: String, _ contact: Patient.Contact, version: Int) async throws -> PatientRead {
        var errors: [FieldError] = []
        checkPatientContact(contact, "contacts", &errors)
        if !errors.isEmpty { throw DomainError.validationFailed(entity: "Patient", errors: errors) }
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Patient", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            guard let changed = try await uow.patients.addContact(id, contact) else {
                throw DomainError.notFound(entity: "Patient", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from contacts, by its position, read at version.
    @discardableResult
    public func removeContact(_ id: String, _ position: Int, version: Int) async throws -> PatientRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Patient", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            if !(current.contacts ?? []).indices.contains(position) {
                throw DomainError.notFound(entity: "Contact", key: "\(position)")
            }
            guard let changed = try await uow.patients.removeContact(id, position, (current.contacts ?? []).count) else {
                throw DomainError.conflict(entity: "Patient", reason: "was changed by someone else since it was read", fields: ["contacts"])
            }
            return read(changed)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var name: String?? = nil
    var birth: Date?? = nil
    var weight: Double?? = nil
    var balance: Decimal?? = nil
    var document: String?? = nil
    var photo: Data?? = nil
    var visits: Int?? = nil
    var blood: String?? = nil
    var contacts: [Patient.Contact]?? = nil
    var insurance: Patient.Insurance?? = nil
    var version: Int?? = nil
}

/// Checks the values against the rules of the "patients" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Patient?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if let value = values.name ?? nil {
        if value.count > 80 {
            errors.append(FieldError("name", "is longer than 80 characters"))
        }
        if !(value.count >= 2) {
            errors.append(FieldError("name", "must have >= 2 characters"))
        }
    } else if creating || values.name != nil {
        errors.append(FieldError("name", "is required"))
    }
    if values.birth ?? nil == nil && (creating || values.birth != nil) {
        errors.append(FieldError("birth", "is required"))
    }
    if let value = values.visits ?? nil {
        if !(Double(value) >= 0.0) {
            errors.append(FieldError("visits", "must be >= 0"))
        }
    } else if creating || values.visits != nil {
        errors.append(FieldError("visits", "is required"))
    }
    if let value = values.blood ?? nil {
        if !["A", "B", "O"].contains(value) {
            errors.append(FieldError("blood", "must be one of: A, B, O"))
        }
    }
    if let value = values.contacts ?? nil {
        for (i0, item0) in value.enumerated() {
            checkPatientContact(item0, "contacts.\(i0)", &errors)
        }
    } else if creating || values.contacts != nil {
        errors.append(FieldError("contacts", "is required"))
    }
    if let value = values.insurance ?? nil {
        checkPatientInsurance(value, "insurance", &errors)
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Patient", errors: errors) }
}

/// Values that must be unique are not taken by another row.
fileprivate func checkUnique(_ uow: any UnitOfWork, _ values: Values, _ current: Patient?) async throws {
    if let document = values.document ?? current?.document,
       let other = try await uow.patients.findByDocument(document),
       current.map({ other.id != $0.id }) ?? true {
        throw DomainError.conflict(entity: "Patient", reason: "document is already taken", fields: ["document"])
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Patient?) async throws {
    try await validate(uow, values, current)
    try await checkUnique(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Patient, _ values: Values) {
    if let value = values.name { entity.name = value }
    if let value = values.birth { entity.birth = value }
    if let value = values.weight { entity.weight = value }
    if let value = values.balance { entity.balance = value }
    if let value = values.document { entity.document = value }
    if let value = values.photo { entity.photo = value }
    if let value = values.visits { entity.visits = value }
    if let value = values.blood { entity.blood = value }
    if let value = values.contacts { entity.contacts = value }
    if let value = values.insurance { entity.insurance = value }
    if let value = values.version { entity.version = value }
}

/// What a Patient.Contact does not follow of its rules, each with the path of its field.
fileprivate func checkPatientContact(_ value: Patient.Contact, _ path: String, _ errors: inout [FieldError]) {
    if let held = value.kind {
        if !["phone", "email"].contains(held) {
            errors.append(FieldError("\(path).kind", "must be one of: phone, email"))
        }
    } else {
        errors.append(FieldError("\(path).kind", "is required"))
    }
    if value.value == nil { errors.append(FieldError("\(path).value", "is required")) }
}

/// What a Patient.Insurance does not follow of its rules, each with the path of its field.
fileprivate func checkPatientInsurance(_ value: Patient.Insurance, _ path: String, _ errors: inout [FieldError]) {
}

/// The values an update gives, by field.
fileprivate func given(_ changes: PatientUpdate) -> Values {
    Values(name: .some(changes.name), birth: .some(changes.birth), weight: .some(changes.weight), balance: .some(changes.balance), document: .some(changes.document), photo: .some(changes.photo), visits: .some(changes.visits), blood: .some(changes.blood), contacts: .some(changes.contacts), insurance: .some(changes.insurance), version: .some(changes.version))
}

/// The Patient with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: String) async throws -> Patient {
    guard let row = try await uow.patients.findById(id) else {
        throw DomainError.notFound(entity: "Patient", key: "\(id)")
    }
    return row
}

/// The Patient as services return it.
fileprivate func read(_ entity: Patient) -> PatientRead {
    PatientRead(id: entity.id!, name: entity.name!, birth: entity.birth!, weight: entity.weight, balance: entity.balance, document: entity.document, photo: entity.photo, visits: entity.visits!, blood: entity.blood, contacts: entity.contacts!, insurance: entity.insurance, version: entity.version)
}

import Foundation

/// Operations on rooms. Each write runs in its own transaction.
public struct RoomService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Room after checking it.
    @discardableResult
    public func createRoom(_ data: RoomCreate) async throws -> RoomRead {
        let values = Values(code: data.code.map(Optional.some), beds: data.beds.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Room()
            applyValues(&entity, values)
            return try await read(uow.rooms.insert(entity))
        }
    }

    /// The Room with this key; notFound when there is none.
    public func getRoom(_ id: String) async throws -> RoomRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of rooms after the key after (nil for the first page), by primary key.
    public func listRooms(after: String?, limit: Int) async throws -> CursorPage<RoomRead, String> {
        try await unitOfWork.rooms.list(after: after, limit: limit).map(read)
    }

    /// Changes the given values of a Room.
    @discardableResult
    public func updateRoom(_ id: String, _ changes: RoomUpdate) async throws -> RoomRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.rooms.update(current))
        }
    }

    /// Deletes a Room.
    public func deleteRoom(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.rooms.delete(current)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var code: String?? = nil
    var beds: Int?? = nil
}

/// Checks the values against the rules of the "rooms" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Room?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.code ?? nil == nil && (creating || values.code != nil) {
        errors.append(FieldError("code", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Room", errors: errors) }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Room?) async throws {
    try await validate(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Room, _ values: Values) {
    if let value = values.code { entity.code = value }
    if let value = values.beds { entity.beds = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: RoomUpdate) -> Values {
    Values(code: .some(changes.code), beds: .some(changes.beds))
}

/// The Room with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: String) async throws -> Room {
    guard let row = try await uow.rooms.findById(id) else {
        throw DomainError.notFound(entity: "Room", key: "\(id)")
    }
    return row
}

/// The Room as services return it.
fileprivate func read(_ entity: Room) -> RoomRead {
    RoomRead(id: entity.id!, code: entity.code!, beds: entity.beds)
}

/// What services depend on: a repository per table and a transaction. Each service operation runs in transaction(): committed when it ends, rolled back when it throws.
public protocol UnitOfWork: Sendable {
    var patients: any PatientRepository { get }
    var rooms: any RoomRepository { get }

    /// Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws.
    func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T
}

/// The repositories over one database, and its transaction.
public struct MongoUnitOfWork: UnitOfWork {
    public let db: Db

    public init(db: Db) {
        self.db = db
    }

    public var patients: any PatientRepository { MongoPatientRepository(db: db) }

    public var rooms: any RoomRepository { MongoRoomRepository(db: db) }

    /// Joins the transaction already open, or opens one.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await db.transaction { transaction in try await work(MongoUnitOfWork(db: transaction)) }
    }
}

/// The in-memory repositories, for tests and for trying the services without a database.
public final class MemoryUnitOfWork: UnitOfWork {
    public let patients: any PatientRepository = MemoryPatientRepository()
    public let rooms: any RoomRepository = MemoryRoomRepository()

    public init() {}

    /// Memory has no transactions: changes are kept as they are made.
    public func transaction<T: Sendable>(_ work: @escaping @Sendable (any UnitOfWork) async throws -> T) async throws -> T {
        try await work(self)
    }
}

